package dev.veltraph.client.core;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class RootOwnEnableReceiptTest {
 static class Parent extends AbstractModule {
  final ModuleManager manager;ModuleManager.OwnEnableReceipt receipt;boolean tentative;int callbacks;Runnable work=()->{};
  Parent(ModuleManager manager,String id){super(id,id,ModuleCategory.MISC);this.manager=manager;}
  public void onEnable(){callbacks++;receipt=manager.currentOwnEnableReceipt(this).orElse(null);tentative=receipt!=null&&receipt.invocationCurrent();if(receipt!=null)assertFalse(receipt.current());work.run();}
 }
 @Test void actualRegisteredEnabledEffectMintsOnlyAfterNormalCallbackReturn(){var m=new ModuleManager();var p=new Parent(m,"p");m.register(p);var before=m.lifecycleSnapshot();p.setEnabled(true);assertNotNull(p.receipt);assertTrue(p.tentative);assertTrue(p.receipt.current());assertTrue(m.ownEnableMatches(p.receipt,before,p));assertEquals(1,p.callbacks);assertEquals(MacroState.RUNNING,p.state());assertTrue(m.currentOwnEnableReceipt(p).isEmpty());}
 @Test void publicOnEnableCallCannotMintActualEffectReceipt(){var m=new ModuleManager();var p=new Parent(m,"p");m.register(p);p.onEnable();assertNull(p.receipt);assertFalse(p.isEnabled());assertEquals(MacroState.STOPPED,p.state());}
 @Test void unregisteredParentCannotMintRegisteredRootReceipt(){var m=new ModuleManager();var p=new Parent(m,"p");p.setEnabled(true);assertNull(p.receipt);assertTrue(p.isEnabled());assertEquals(1,p.callbacks);}
 @Test void equalTrueWriteDoesNotMintAnotherInvocation(){var m=new ModuleManager();var p=new Parent(m,"p");m.register(p);p.setEnabled(true);var real=p.receipt;p.setEnabled(true);assertSame(real,p.receipt);assertEquals(1,p.callbacks);assertTrue(m.currentOwnEnableReceipt(p).isEmpty());}
 @Test void unrelatedLateControllerEnableRefusesReceiptAndPreservesOriginalCallbacks(){var m=new ModuleManager();var p=new Parent(m,"p");var q=new Parent(m,"q");m.register(p);m.register(q);p.work=()->q.setEnabled(true);p.setEnabled(true);assertFalse(p.receipt.current());assertTrue(p.isEnabled());assertTrue(q.isEnabled());assertEquals(1,p.callbacks);assertEquals(1,q.callbacks);}
 @Test void reentrantSelfDisableEnableAbaRevokesOriginalPrivateInvocation(){var m=new ModuleManager();var p=new Parent(m,"p");m.register(p);ModuleManager.OwnEnableReceipt[] first={null};p.work=()->{first[0]=p.receipt;p.work=()->{};p.setEnabled(false);p.setEnabled(true);};p.setEnabled(true);assertNotNull(first[0]);assertFalse(first[0].current());assertTrue(p.isEnabled());assertEquals(2,p.callbacks);}
 @Test void actualCallbackExceptionNeverCertifiesReceiptOrChangesOriginalExceptionState(){var m=new ModuleManager();var p=new Parent(m,"p");m.register(p);p.work=()->{throw new IllegalStateException("native callback failed");};assertThrows(IllegalStateException.class,()->p.setEnabled(true));assertNotNull(p.receipt);assertFalse(p.receipt.current());assertFalse(p.receipt.invocationCurrent());assertTrue(m.currentOwnEnableReceipt(p).isEmpty());assertTrue(p.isEnabled());assertEquals(MacroState.RUNNING,p.state());}
 @Test void lateRegistrationOrSupplierRebindRefusesCurrentReceipt(){var m=new ModuleManager();var p=new Parent(m,"p");m.register(p);p.work=()->m.register(new Parent(m,"q"));p.setEnabled(true);assertFalse(p.receipt.current());p.setEnabled(false);p.work=()->m.leasedInputOwner(()->p);p.setEnabled(true);assertFalse(p.receipt.current());}
 @Test void wrongOrOldDisabledSnapshotCannotLaunderRealEnable(){var m=new ModuleManager();var p=new Parent(m,"p");m.register(p);var old=m.lifecycleSnapshot();p.setEnabled(true);p.setEnabled(false);var actual=m.lifecycleSnapshot();p.setEnabled(true);assertFalse(m.ownEnableMatches(p.receipt,old,p));assertTrue(m.ownEnableMatches(p.receipt,actual,p));}
 @Test void parentPausedDuringCallbackIsUnknownWithoutChangingOriginalState(){var m=new ModuleManager();var p=new Parent(m,"p");m.register(p);p.work=()->p.setState(MacroState.PAUSED);p.setEnabled(true);assertFalse(p.receipt.current());assertEquals(MacroState.PAUSED,p.state());assertTrue(p.isEnabled());}
 @Test void sameObjectRegisteredToTwoManagersRefusesScopedReceiptOnly(){var m=new ModuleManager();var n=new ModuleManager();var p=new Parent(m,"p");m.register(p);n.register(p);p.setEnabled(true);assertNull(p.receipt);assertTrue(p.isEnabled());assertEquals(1,p.callbacks);}
 @Test void callbackFreeReceiptsNeverInvokeRoleOrInputSupplierGetters(){var m=new ModuleManager();var p=new Parent(m,"p"){public boolean ownsGameplayInput(){fail("role callback");return false;}public boolean isPassiveObserver(){fail("passive callback");return false;}};m.register(p);m.leasedInputOwner(()->{fail("supplier callback");return null;});var old=m.lifecycleSnapshot();p.setEnabled(true);assertTrue(m.ownEnableMatches(p.receipt,old,p));}
}
